package vn.nanase.hako.tests;
import android.app.*;import android.content.*;import android.os.*;import java.util.*;import vn.nanase.hako.*;
public final class SyncDomainTest extends Instrumentation {
 int checks;void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);Bundle b=new Bundle();b.putString("stream","PASS "+label+"\n");sendStatus(0,b);}
 public void onCreate(Bundle args){super.onCreate(args);start();}
 public void onStart(){Bundle result=new Bundle();try{
  Context c=getTargetContext();Diagnostics.start(c);c.getSharedPreferences("settings",0).edit().putString("origin","https://docln.sbs").putBoolean("sync_paused",true).commit();HakoParser.ORIGIN="https://docln.sbs";Store s=Store.get(c);
  String id="truyen-999037",url="https://docln.sbs/truyen/999037-fixture";s.putBook(new HakoParser.Link(id,"Fixture",url));List<HakoParser.Link> links=new ArrayList<>();links.add(new HakoParser.Link(id+"-1","Chương 1",url+"/c1-old"));s.catalog(id,links);s.followed(id,true,0);Store.write(s.html(id+"-1"),"<p>Nội dung đã tải hợp lệ để kiểm tra giữ cache và mốc đọc.</p>");s.state(id+"-1",true,"");s.completeThrough(id,id+"-1");
  Store.ReadRequest first=s.readRequest(id);check(first!=null,"Last text completion creates durable request");s.queueCaughtUp(id);check(s.sameReadRequest(first),"Unchanged request does not change generation");
  String missing="<table><tr><td><a href='"+url+"'>Fixture</a></td></tr></table>";Map<String,Store.ReadRequest> observed=s.readRequests();ReadSync.observeShelf(c,missing,observed);check(!s.queued(id),"Verified absent button retires original request");s.queueCaughtUp(id);check(!s.queued(id),"Same missing-button tip cannot recreate pending");
  String button="<table><tr><td><a href='"+url+"'>Fixture</a></td><td><a class='mark-read' data-series='999037' data-unread='1'>Đọc hết</a></td></tr></table>";
  ReadSync.observeShelf(c,button);check(s.queued(id),"Returned button automatically recovers request without manual queue");Store.ReadRequest recovered=s.readRequest(id);check(!s.sameReadRequest(first),"Recovered request has new generation");ReadSync.observeShelf(c,missing,observed);check(s.sameReadRequest(recovered),"Old shelf reply cannot remove recovered request");
  s.resetUnreadForFull(id);s.completeThrough(id,id+"-1");Store.ReadRequest afterReset=s.readRequest(id);check(!s.retireReadRequest(recovered,true)&&s.sameReadRequest(afterReset),"Old reply cannot retire same-tip request after full reset");
  ReadSync.publish(c,id,"WAIT_NETWORK","fixture");check(ReadSync.report(c).getInt("count")==1&&ReadSync.report(c).getJSONObject("states").getJSONObject(id).getString("state").equals("WAIT_NETWORK"),"Report exposes waiting state and queue count");
  TocState.refresh(c,id);OperationTrace.Span metadata=OperationTrace.begin("test.metadata");s.pin(id,true);check(TocState.peek(id)!=null&&TocState.peek(id).book.pinned,"Metadata-only pin keeps live TOC book fresh");OperationTrace.end(metadata,"ok",0);check(OperationTrace.payload().getJSONObject("totals").getJSONArray("test.metadata").getLong(6)==0,"Metadata-only pin does not query chapter rows");LibraryState.refresh(c);String before=Store.read(s.html(id+"-1"));s.rebase("https://docln.net");check(s.book(id).url.equals("https://docln.net/truyen/999037-fixture"),"Rebase commits book URL");check(s.chapter(id,id+"-1").url.equals("https://docln.net/truyen/999037-fixture/c1-old"),"Rebase commits chapter URL");check(Store.read(s.html(id+"-1")).equals(before)&&s.unread(id)==0,"Rebase preserves content and read watermark");boolean removed=false;try{TocState.readSaved(c,id);}catch(java.io.FileNotFoundException expected){removed=true;}check(removed,"Rebase evicts obsolete derived disk TOC");check(c.getSharedPreferences("settings",0).getString("origin","").equals("https://docln.net"),"Rebase persists selected origin");
  check(!s.retireReadRequest(recovered,false)&&s.sameReadRequest(afterReset),"Domain change preserves request generation");
  result.putString("stream","PASS TOTAL "+checks+" sync/domain checks\n");finish(0,result);
 }catch(Throwable e){result.putString("stream","FAIL "+e+"\n");finish(1,result);}}
}
